def solve(payload):
    stock=dict(payload.get('stock',{})); reserved={k:0 for k in stock}; applied=[]
    for e in payload.get('events',[]):
        if e['op']=='receive': stock[e['sku']]+=e['qty']
        elif e['op']=='reserve' and stock[e['sku']]>=e['qty']: stock[e['sku']]-=e['qty']; reserved[e['sku']]+=e['qty']
        applied.append(e['id'])
    return {'stock':stock,'reserved':reserved,'applied':applied,'rejected':[],'ignored':[]}

def solve(payload):
    stock=dict(payload.get('stock',{})); reserved={k:0 for k in stock}; applied=[]
    for e in payload.get('events',[]):
        if e['op']=='ship' and stock.get(e['sku'],0)>=e['qty']: stock[e['sku']]-=e['qty']; applied.append(e['id'])
    return {'stock':stock,'reserved':reserved,'applied':applied,'rejected':[],'ignored':[]}
